BEGIN;ALTER TABLE work_assignments ADD COLUMN IF NOT EXISTS check_in_lat double precision,ADD COLUMN IF NOT EXISTS check_in_lng double precision,ADD COLUMN IF NOT EXISTS check_out_lat double precision,ADD COLUMN IF NOT EXISTS check_out_lng double precision;ALTER TABLE work_assignments ADD CONSTRAINT work_assignments_check_in_lat_range CHECK(check_in_lat IS NULL OR check_in_lat BETWEEN -90 AND 90),ADD CONSTRAINT work_assignments_check_in_lng_range CHECK(check_in_lng IS NULL OR check_in_lng BETWEEN -180 AND 180),ADD CONSTRAINT work_assignments_check_out_lat_range CHECK(check_out_lat IS NULL OR check_out_lat BETWEEN -90 AND 90),ADD CONSTRAINT work_assignments_check_out_lng_range CHECK(check_out_lng IS NULL OR check_out_lng BETWEEN -180 AND 180);COMMIT;
